(window.webpackJsonpGUI=window.webpackJsonpGUI||[]).push([[92],{1431:function(n,t,e){"use strict";e.r(t),t.default={code:"114EMiaoli",title:"114-苗栗縣國小",unlockCode:"114EMiaoli",tasks:[{id:"114EMiaoli-1",code:"114EMiaoli-114EMiaoli-1",title:"1-苗栗項鍊",description:"苗栗縣政府決定發放由英文字母M與L珠子串連的項鍊給市民作紀念。由於每個人需要的尺寸不同，尺寸1的項鍊表示英文字母M與L珠子各一顆，形成字串ML 尺寸2的項鍊表示英文字母M與L珠子各二顆，也就會形成字串MLML。尺寸更大的項鍊，就會形成重複該次數的字串ML。\n請使用 Scratch3撰寫一個程式專案，根據項鍊的尺寸，幫忙印出項鍊的珠子形成的字串。\n【輸入格式】\n「詢問...並等待」一次後，這次「詢問的答案」會得到：項鍊的尺寸。(1~100)\n【輸出格式】\n回答恰好一次，請回答項鍊的珠子形成的字串，中間不可以有空格或任何其他符號。(僅需輸出該字串)。",examples:[{input:"1",output:"ML",explanation:"程式詢問一次，得到回答1。\n答案是字串ML，所以用「說出」積木回答說出ML。"},{input:"2",output:"MLML",explanation:"程式詢問一次，得到回答2。\n答案是字串 MLML，所以用「說出」積木回答，說出 MLML。"},{input:"5",output:"MLMLMLMLML",explanation:"程式詢問一次，得到回答5。\n答案是字串 MLMLMLMLML，所以用「說出」積木回答，說出 MLMLMLMLML。"}],testCases:[{input:"1",expectedOutput:"ML",score:10},{input:"2",expectedOutput:"MLML",score:10},{input:"5",expectedOutput:"MLMLMLMLML",score:10},{input:"3",expectedOutput:"MLMLML",score:10},{input:"4",expectedOutput:"MLMLMLML",score:10},{input:"10",expectedOutput:"MLMLMLMLMLMLMLMLMLML",score:10},{input:"6",expectedOutput:"MLMLMLMLMLML",score:10},{input:"7",expectedOutput:"MLMLMLMLMLMLML",score:10},{input:"8",expectedOutput:"MLMLMLMLMLMLMLML",score:10},{input:"9",expectedOutput:"MLMLMLMLMLMLMLMLML",score:10}],difficulty:"L2",sb3Path:"m0/114EMiaoli/114EMiaoli-1.sb3"},{id:"114EMiaoli-2",code:"114EMiaoli-114EMiaoli-2",title:"2-點名報數",description:"期待已久的寒假終於快要開始了！但是今天班上有一個同學沒有來上學考試，也沒有請假。老師迷迷糊糊，已經分不清楚是誰沒來了，於是決定請大家點名報數，這樣就能知道是誰沒有來。\n這個班級的座號從1開始，依照1,2,3,... 順序編下去，中間不會有跳號，直到最後一號，也就是班級的總人數。大家會依照自己的座號順序，依照從小到大的順序報數。舉例來說，如果總共有5個學生，點名報數時，報的座號是1,2,4,5，那麼老師就知道座號3的同學沒有來。請使用Scratch撰寫一個程式專案，根據所有學生從小到大的順序報數，幫老師找出是誰沒有來上學考試。\n【輸入格式】\n「詢問...並等待」一次後，這次「詢問的答案」會得到：班級的總人數。(2~20人)\n接著繼續使用「詢問...並等待」取得依照從小到大的順序每次報數，次數比「班級的總人數」少一次：\n每次「詢問...並等待」後，「詢問的答案」得到整數：這次報數的座號。\n保證不會有不存在的座號，一定遞增，也不會重複。\n【輸出格式】\n回答恰好一次，「說出」沒有來上學考試的座號。(僅需輸出該座號)。",examples:[{input:"4\n1\n2\n4",output:"3",explanation:"得到回答4，表示「班級的總人數」為4，也就是說全班有4人，座號分別是1,2,3,4。\n繼續詢問總共3次。分別得到回答1、2、4。\n程式經過計算後，得出沒有來上學考試的是座號3，所以用「說出」積木回答，說出3。"},{input:"5\n1\n2\n3\n4",output:"5",explanation:"得到回答5，表示「班級的總人數」為5，全班有5人，座號分別是1, 2, 3, 4, 5。\n繼續詢問總共4次。分別得到回答1、2、3、4。\n得出沒有來上學考試的是座號5，所以用「說出」積木回答，說出5。"}],testCases:[{input:"4\n1\n2\n4",expectedOutput:"3",score:10},{input:"5\n1\n2\n3\n4",expectedOutput:"5",score:10},{input:"3\n2\n3",expectedOutput:"1",score:10},{input:"6\n1\n3\n4\n5\n6",expectedOutput:"2",score:10},{input:"7\n1\n2\n3\n4\n6\n7",expectedOutput:"5",score:10},{input:"2\n1",expectedOutput:"2",score:10},{input:"2\n2",expectedOutput:"1",score:10},{input:"8\n1\n2\n3\n4\n5\n6\n8",expectedOutput:"7",score:10},{input:"9\n1\n2\n3\n4\n5\n6\n7\n8",expectedOutput:"9",score:10},{input:"10\n1\n2\n3\n4\n5\n6\n8\n9\n10",expectedOutput:"7",score:10}],difficulty:"L2",sb3Path:"m0/114EMiaoli/114EMiaoli-2.sb3"},{id:"114EMiaoli-3",code:"114EMiaoli-114EMiaoli-3",title:"3-最大人數",description:"在一個偌大的禮堂中，人潮進進出出參觀展覽。為了安全起見，老師指派一個學生守著出入口，每當有人進入或離開，就記錄下來，這樣就可以從記錄中，得到在禮堂人數最多時，禮堂中總共有多少人。\n禮堂一開始沒有人，每當有人進入時，這位學生就會在紙上多寫下英文字母A；每當有人離開時，這位學生就會在紙上多寫下英文字母B。這張紙上的字母一定會依照順序寫下，不會被擦除。除此之外，紙上不會有其他的東西。\n舉例來說，如果現在紙上寫著AAABABBB，那麼老師就可以知道：現在禮堂中沒有人，且在最多人時總共有3個人；另外，如果現在紙上寫著ABAB，那麼老師就可以知道現在禮堂中沒有人，且在最多人時總共有1個人。\n負責記錄的學生非常乖，因此記錄下來的資料一定正確，且最終進入禮堂的所有人都會離開。\n【輸入格式】\n「詢問...並等待」一次後，這次「詢問的答案」會得到現在紙上寫著什麼。\n• 紙上的紀錄長度在1至10之間。\n• 紙上只會有英文字母A與B。\n【輸出格式】\n總共回答恰好一次，請輸出禮堂最多人時總共有多少人，「說出」禮堂中最多的人數。(僅需輸出數字)。",examples:[{input:"AAABABBB",output:"3",explanation:"得到回答 AAABABBB，表示「紙上的紀錄」為AAABABBB。\n程式經過計算，禮堂人數最多時總共有3人，所以用「說出」積木回答，說出3。"},{input:"ABAB",output:"1",explanation:"得到回答 ABAB，表示「紙上的紀錄」為ABAB。\n程式經過計算，禮堂人數最多時總共有1人，所以用「說出」積木回答，說出1。"}],testCases:[{input:"AAABABBB",expectedOutput:"3",score:10},{input:"ABAB",expectedOutput:"1",score:10},{input:"AB",expectedOutput:"1",score:10},{input:"AABB",expectedOutput:"2",score:10},{input:"AAAAABBBBB",expectedOutput:"5",score:10},{input:"ABAABB",expectedOutput:"2",score:10},{input:"AABABB",expectedOutput:"2",score:10},{input:"AAABBBABAB",expectedOutput:"3",score:10},{input:"AABBAABB",expectedOutput:"2",score:10},{input:"AAAABBBB",expectedOutput:"4",score:10}],difficulty:"L2",sb3Path:"m0/114EMiaoli/114EMiaoli-3.sb3"},{id:"114EMiaoli-4",code:"114EMiaoli-114EMiaoli-4",title:"4-跳健康操",description:"班上有男生與女生，現在要組隊跳健康操，每一組兩個人，一男一女，且這兩個人的身高必須相同。已知男生與女生的身高都已經各自從小到大排好，請使用Scratch3撰寫一個程式專案，根據每一位男生與女生的身高，幫忙求出最多可以組成多少組。\n每個人最多同時只能在一組中，但也可能沒有被分組。\n【輸入格式】\n先詢問男生的部分：\n「詢問...並等待」一次後，這次「詢問的答案」會得到：男生的人數。(1~100人)\n接著繼續使用「詢問...並等待」取得每個男生的身高，次數與「男生的人數」相同：每次得到整數：其中一個男生的身高(100~200)。每個男生的身高會依照詢問的順序遞增回答(從小到大，或相同)。\n然後詢問女生的部分：\n「詢問...並等待」一次後，這次「詢問的答案」會得到：女生的人數。(1~100人)\n接著繼續使用「詢問...並等待」取得每個女生的身高，次數與「女生的人數」相同：每次得到整數：其中一個女生的身高(100~200)。每個女生的身高會依照詢問的順序遞增回答(從小到大，或相同)。\n【輸出格式】\n回答一次，請「說出」最多可以組成多少組。(僅需輸出數字)。",examples:[{input:"2\n120\n130\n3\n120\n120\n130",output:"2",explanation:"得到回答2，表示「男生的人數」為2，男生有2人。\n依序得到回答120, 130，表示2個男生的身高。\n得到回答3，表示「女生的人數」為3，女生有3人。\n依序得到回答120, 120, 130，表示3個女生的身高。\n程式經過計算後，得出最多可以組成2組，所以總共用「說出」積木回答，說出2。"},{input:"1\n200\n1\n200",output:"1",explanation:"得到回答1, 200, 1, 200 表示男生與女生各有1人，身高皆為200。\n得出最多可以組成1組，所以說出1。"}],testCases:[{input:"2\n120\n130\n3\n120\n120\n130",expectedOutput:"2",score:10},{input:"1\n200\n1\n200",expectedOutput:"1",score:10},{input:"3\n140\n150\n160\n3\n140\n150\n160",expectedOutput:"3",score:10},{input:"4\n100\n110\n120\n130\n4\n140\n150\n160\n170",expectedOutput:"0",score:10},{input:"3\n150\n150\n150\n2\n150\n150",expectedOutput:"2",score:10},{input:"2\n130\n130\n4\n130\n130\n130\n130",expectedOutput:"2",score:10},{input:"5\n110\n120\n130\n140\n150\n5\n120\n130\n140\n150\n160",expectedOutput:"4",score:10},{input:"1\n100\n2\n110\n120",expectedOutput:"0",score:10},{input:"2\n150\n160\n1\n160",expectedOutput:"1",score:10},{input:"3\n140\n140\n150\n3\n140\n150\n150",expectedOutput:"2",score:10}],difficulty:"L2",sb3Path:"m0/114EMiaoli/114EMiaoli-4.sb3"},{id:"114EMiaoli-5",code:"114EMiaoli-114EMiaoli-5",title:"5-進位運算",description:"數學老師發現大家算數時常常粗心大意，連基本的加減法都不太熟...於是老師決定出一大堆加法的練習題給大家來練習，由於總是有偷懶的學生使用計算機幫忙算，這樣就沒有練習到了，所以老師要求只需要回答進行加法運算中，發生進位的次數。\n在十進位的直式加法中，依位數由低位到高位逐位相加。若某一位上「本位相加的和(包含上一位帶來的進位)」大於或等於10，則在本位寫下該和的個位數，並把1加到左邊相鄰的高一位(也就是把10個本位合成1個高一位)。這個「把1送到高一位」的處理，稱為「進位」。\n「進位的次數」定義為：在完成整個直式加法的計算過程中，因為某一位的相加結果(包含上一位的進位)大於或等於10，而產生「向左邊高一位送出1」之動作的總次數。每一個位數只要實際產生一次進位，就計為1次；若連續多位都各自產生進位，則每一位產生的進位都要分別計次。\n舉例來說，當計算999加1時，總共發生了3次進位；而計算1998加37時，總共也發生了3次進位；但是計算2008加17時，總共只發生了1次進位。\n【輸入格式】\n「詢問...並等待」第一次後，這次「詢問的答案」會得到：被加數。(1~1000000)\n「詢問...並等待」第二次後，這次「詢問的答案」會得到：加數。(1~1000000)\n【輸出格式】\n回答恰好一次，「說出」總共發生幾次進位。(僅需輸出數字)。",examples:[{input:"999\n1",output:"3",explanation:"得到回答999，表示「被加數」為999。\n得到回答1，表示「加數」為1。\n程式經過計算後，得出加法總共發生了三次進位，所以用「說出」積木回答，說出3。"},{input:"2008\n17",output:"1",explanation:"得到回答2008，表示「被加數」為2008。\n得到回答17，表示「加數」為17。\n程式經過計算後，得出加法總共發生了一次進位，所以用「說出」積木回答，說出1。"}],testCases:[{input:"999\n1",expectedOutput:"3",score:10},{input:"2008\n17",expectedOutput:"1",score:10},{input:"1998\n37",expectedOutput:"3",score:10},{input:"123\n456",expectedOutput:"0",score:10},{input:"555\n555",expectedOutput:"3",score:10},{input:"9\n9",expectedOutput:"1",score:10},{input:"999999\n1",expectedOutput:"6",score:10},{input:"1000\n1000",expectedOutput:"0",score:10},{input:"909\n91",expectedOutput:"3",score:10},{input:"888\n222",expectedOutput:"3",score:10}],difficulty:"L2",sb3Path:"m0/114EMiaoli/114EMiaoli-5.sb3"}]}}}]);